import{_ as e}from"./chunks/100.Bym1HttY.js";import{_ as o,o as a,c as n,ak as r}from"./chunks/framework.Ba6sv-31.js";const i="/projects/AiBlockSensor/en/latest/assets/1.B6XL9-GO.webp",s="/projects/AiBlockSensor/en/latest/assets/2.IYugdgLh.webp",l="/projects/AiBlockSensor/en/latest/assets/3.CLaop-ui.webp",d="/projects/AiBlockSensor/en/latest/assets/4.NDCSJVtB.webp",f=JSON.parse('{"title":"2. Button Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2. Button Module.md","filePath":"docs/2. Button Module.md"}'),c={name:"docs/2. Button Module.md"};function u(h,t,p,m,g,b){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_2-button-module" tabindex="-1">2. Button Module <a class="header-anchor" href="#_2-button-module" aria-label="Permalink to &quot;2. Button Module&quot;">​</a></h1><h2 id="_2-1-introduction" tabindex="-1">2.1 Introduction <a class="header-anchor" href="#_2-1-introduction" aria-label="Permalink to &quot;2.1 Introduction&quot;">​</a></h2><p>The button module comes equipped with a white button cap and is widely used across various maker DIY projects, including environmental monitoring systems, electronic scales, robot cars, and robotics.</p><img loading="lazy" height="805" width="1109" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_2-2-technical-specifications" tabindex="-1">2.2 Technical Specifications <a class="header-anchor" href="#_2-2-technical-specifications" aria-label="Permalink to &quot;2.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Trigger mode</td><td style="text-align:center;">Press trigger</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 24.0 mm</td></tr></tbody></table><h2 id="_2-3-hands-on-project" tabindex="-1">2.3 Hands-On Project <a class="header-anchor" href="#_2-3-hands-on-project" aria-label="Permalink to &quot;2.3 Hands-On Project&quot;">​</a></h2><h3 id="_2-3-1-project-introduction" tabindex="-1">2.3.1 Project Introduction <a class="header-anchor" href="#_2-3-1-project-introduction" aria-label="Permalink to &quot;2.3.1 Project Introduction&quot;">​</a></h3><p>This project uses the button module and the controller&#39;s onboard buzzer to create a simple push-button doorbell. When the button module is pressed, the buzzer continuously plays note C5. Once released, the buzzer stops immediately, demonstrating the detection logic of the button module.</p><h3 id="_2-3-2-hardware-wiring" tabindex="-1">2.3.2 Hardware Wiring <a class="header-anchor" href="#_2-3-2-hardware-wiring" aria-label="Permalink to &quot;2.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the button module to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="1080" width="1380" src="'+s+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among A, B, C, or D on the controller. Ensure that the port selected in the program matches the physical wiring.</strong></p></div><h3 id="_2-3-3-adding-extensions" tabindex="-1">2.3.3 Adding Extensions <a class="header-anchor" href="#_2-3-3-adding-extensions" aria-label="Permalink to &quot;2.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Key module</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_2-3-4-complete-program-and-analysis" tabindex="-1">2.3.4 Complete Program and Analysis <a class="header-anchor" href="#_2-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;2.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the status of the button module is continuously monitored.</p></li><li><p>Condition check: Read the button module on port A to detect whether the button is pressed.</p><ul><li><p>If the button is pressed: The buzzer plays note C5 continuously in the background.</p></li><li><p>If released: The buzzer turns off, stopping sound output.</p></li></ul></li></ol><img loading="lazy" height="525" width="1050" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1fLfLXEVjSMZdojOq7C44xJqZIBm4MDem?usp=sharing" target="_blank" rel="noreferrer">Program Files/ 02 Button Module.sb3</a>.</strong></p></div><h3 id="_2-3-5-program-upload" tabindex="-1">2.3.5 Program Upload <a class="header-anchor" href="#_2-3-5-program-upload" aria-label="Permalink to &quot;2.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_2-3-6-program-outcome" tabindex="-1">2.3.6 Program Outcome <a class="header-anchor" href="#_2-3-6-program-outcome" aria-label="Permalink to &quot;2.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, pressing the button module connected to port A causes the buzzer to play tone C5 continuously. Releasing the button module immediately silences the buzzer, creating an interactive doorbell.</p>',25)])])}const x=o(c,[["render",u]]);export{f as __pageData,x as default};
